from __future__ import annotations

import json
from pathlib import Path

from workflow.run_case import (
    load_fixture,
    run_scientific_workflow,
    summarize,
)


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    try:
        rendered = json.dumps(payload, indent=2, sort_keys=True, allow_nan=False) + "\n"
    except (TypeError, ValueError):
        exit_code = 2
        rendered = json.dumps(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": "report_serialization_failed",
            },
            indent=2,
            sort_keys=True,
        ) + "\n"
    REPORT_FILE.write_text(rendered, encoding="utf-8")
    print(rendered, end="")
    return exit_code


def main() -> int:
    try:
        data = load_fixture()
        outputs = run_scientific_workflow(data)
        observation = summarize(outputs, data)
    except Exception:  # noqa: BLE001 - lifecycle state is intentional.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": "workflow_execution_failed",
            },
            2,
        )

    if not observation["finite"]:
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "reason_category": "non_finite_scientific_output",
                "observation": observation,
            },
            1,
        )

    return write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed",
            "observation": observation,
        },
        0,
    )


if __name__ == "__main__":
    raise SystemExit(main())

